type Nullable<T> = T | null;

function firstOrNull<T>(arr: T[]): Nullable<T> {
  return arr.length ? arr[0] : null;
}

console.log(firstOrNull([1, 2, 3])); // 1
console.log(firstOrNull([]));        // null

